function drawImageSprite(img,x,y,w,h,rotation=0,alpha=1,glow=''){if(!img||!img.complete||!img.naturalWidth)return false;g.save();g.translate(x,y);g.rotate(rotation);g.globalAlpha=alpha;if(glow){g.shadowColor=glow;g.shadowBlur=22;}g.drawImage(img,-w/2,-h/2,w,h);g.restore();return true}
function fallbackPlayerShip(){g.fillStyle='#29dfff';g.beginPath();g.moveTo(0,-38);g.lineTo(15,-9);g.lineTo(34,12);g.lineTo(28,28);g.lineTo(7,15);g.lineTo(0,26);g.lineTo(-7,15);g.lineTo(-28,28);g.lineTo(-34,12);g.lineTo(-15,-9);g.closePath();g.fill();g.fillStyle='#e7fbff';g.beginPath();g.moveTo(0,-22);g.lineTo(8,7);g.lineTo(-8,7);g.fill();g.fillStyle=ship==='titan'?'#ff6d38':ship==='specter'?'#b975ff':'#ffb33a';g.fillRect(-15,23,8,12+rnd(0,7));g.fillRect(7,23,8,12+rnd(0,7));if(ship==='titan'){g.strokeStyle='#ffc08d';g.lineWidth=6;g.strokeRect(-32,-3,64,24)}if(ship==='specter'){g.fillStyle='#bb9aff';g.beginPath();g.arc(0,4,9,0,Math.PI*2);g.fill()}}
function drawEnemySprite(f){const img=enemySprites[f.type];const size=f.type==='heavy'?86:f.type==='zig'?74:66;const rot=f.type==='zig'?Math.sin(f.age*5)*0.09:0;const glow=f.elite?'#b55cff':f.type==='heavy'?'#ff6848':'#ff4e83';if(drawImageSprite(img,f.x,f.y,size,size,rot,1,glow)){if(f.elite){g.save();g.translate(f.x,f.y);g.strokeStyle='rgba(201,99,255,.9)';g.shadowColor='#cf6bff';g.shadowBlur=24;g.lineWidth=3;g.beginPath();g.arc(0,0,size*.44,0,Math.PI*2);g.stroke();g.restore()}return true}return false}
function fallbackEnemySprite(f){g.save();g.translate(f.x,f.y);g.shadowColor=f.type==='heavy'?'#f25b52':'#e4a04c';g.shadowBlur=12;g.fillStyle=f.elite?'#ad4bff':f.type==='heavy'?'#d34c60':'#d9a15b';g.beginPath();g.moveTo(0,24);g.lineTo(-28,-14);g.lineTo(0,-5);g.lineTo(28,-14);g.closePath();g.fill();g.restore()}
for(let i=0;i<95;i++)stars.push({x:Math.random()*W,y:Math.random()*H,s:Math.random()*2+.3,v:25+Math.random()*65});
