 state='ending';bombBtn.style.display='none';hideBtn.style.display='none';freezeBtn.style.display='none';pauseBtn.style.display='none';panel.style.display='block';
 caseCleared[3]=true;caseUnlocked=3;caseBest[3]=Math.max(caseBest[3]||0,score);persist();
