document.querySelector('#start').onclick=()=>{initAudio();menu()};
function point(e){if(state==='market'){marketMission.point(e);return}if(state==='office'){officeMission.point(e);return}let r=c.getBoundingClientRect();target.x=clamp((e.clientX-r.left)/r.width*W,30,W-30);target.y=clamp((e.clientY-r.top)/r.height*H-65,150,H-45)}
